-- 1 A｜建立並重設練習資料
CREATE TABLE IF NOT EXISTS stock_race_demo (
  sku_id integer PRIMARY KEY,
  available integer NOT NULL CHECK (available >= 0),
  version_no integer NOT NULL
);
INSERT INTO stock_race_demo VALUES (42, 1, 3)
ON CONFLICT (sku_id) DO UPDATE SET available = 1, version_no = 3;

-- 2 A｜先鎖住庫存，讀到 1
BEGIN ISOLATION LEVEL READ COMMITTED;
SELECT available FROM stock_race_demo WHERE sku_id = 42 FOR UPDATE;

-- 3 B｜嘗試鎖同一列，等待時切回 A
BEGIN ISOLATION LEVEL READ COMMITTED;
SELECT available FROM stock_race_demo WHERE sku_id = 42 FOR UPDATE;

-- 4 A｜依剛讀到的庫存扣一件，再提交
UPDATE stock_race_demo
SET available = available - 1, version_no = version_no + 1
WHERE sku_id = 42 AND available >= 1
RETURNING available, version_no;
COMMIT;

-- 5 B｜剛才的 SELECT 已回傳 0 件，跳過扣減並結束交易
ROLLBACK;

-- 6 A｜核對最後庫存與版本
SELECT available, version_no FROM stock_race_demo WHERE sku_id = 42;
